static void Hacl_EC_Point_copy(uint64_t *output, uint64_t *input)
{
  memcpy(output, input, (uint32_t)5U * sizeof input[0U]);
  memcpy(output + (uint32_t)5U,
    input + (uint32_t)5U,
    (uint32_t)5U * sizeof (input + (uint32_t)5U)[0U]);
}

int main(void) {
    char *nature_root = getenv("NATURE_ROOT");
    assert_true(nature_root != NULL);

    // the package-root target is named after package.toml and carries mod
    assert_entry_output("buildtarget.n", "target_main", "entry:buildtarget\n");

    // the target is the whole of buildtarget.cmd, with main defined in cmd/start.n;
    // a plain path selects plat.<os>.n by the normal target priority
    assert_entry_output("cmd/cmd.n", "target_cmd_server", "entry:buildtarget.cmd serving variant\n");
    assert_entry_output("cmd/start.n", "target_cmd_start", "entry:buildtarget.cmd serving variant\n");

    // explicitly passing the variant active for the current target points at the same module
#ifdef __DARWIN
    assert_entry_output("cmd/plat.darwin.n", "target_cmd_plat",
                        "entry:buildtarget.cmd serving variant\n");
    assert_entry_error("cmd/plat.linux.n", "target_cmd_plat_linux",
                       "cmd/plat.linux.n:1:1: build entry 'cmd/plat.linux.n' is not active for target "
                       "darwin_arm64, active source is 'cmd/plat.darwin.n'\n");
#endif
#ifdef __LINUX
    assert_entry_output("cmd/plat.linux.n", "target_cmd_plat",
                        "entry:buildtarget.cmd serving variant\n");
#endif

    // a standalone file module builds only itself, a main in a dependency (buildtarget.lib) is not an entry candidate
    assert_entry_output("standalone.n", "target_standalone", "entry:buildtarget.standalone helper\n");

    // when that same buildtarget.lib is the explicit build target, its own main becomes the entry
    assert_entry_output("lib/lib.n", "target_lib", "should never be selected\n");

    // a target module without a valid main must error
    // diagnostics use the real physical path while the module ident comes from package.toml.name
    assert_entry_error("nomain/nomain.n", "target_nomain",
                       "20260726_03_build_target/nomain/nomain.n:5:15: fn 'main' is undeclared in module "
                       "buildtarget.nomain\n");

    return 0;
}

int main(void){
    CHECK(q38_decode_rate(0,1.0)==0.0);
    CHECK(q38_decode_rate(1,1e-9)==0.0);
    CHECK(q38_decode_rate(2,0.5)==2.0);
    CHECK(q38_decode_rate(3,0.5)==4.0);
    CHECK(q38_decode_rate(3,0.0)==0.0);

    CHECK(q38_cache_hit_percent(0,0)==0.0);
    CHECK(q38_cache_hit_percent(3,0)==100.0);
    CHECK(q38_cache_hit_percent(0,7)==0.0);
    CHECK(q38_cache_hit_percent(3,1)==75.0);

    Q38Timers before={0},after={0};
    for(int i=0;i<Q38_TM_COUNT;i++){
        before.seconds[i]=(double)i;
        after.seconds[i]=(double)i+0.25*(i+1);
    }
    before.forwards=7;after.forwards=11;
    Q38Timers delta=q38_tm_delta(&after,&before);
    for(int i=0;i<Q38_TM_COUNT;i++)CHECK(close_enough(delta.seconds[i],0.25*(i+1)));
    CHECK(delta.forwards==4);

    Q38Timers profile={0};
    profile.seconds[Q38_TM_EXPERT_READ]=0.1;
    profile.seconds[Q38_TM_FP8_EXPAND]=0.2;
    profile.seconds[Q38_TM_ROUTED_EXPERT]=0.3;
    profile.seconds[Q38_TM_SHARED_EXPERT]=0.4;
    profile.seconds[Q38_TM_DELTANET]=0.5;
    profile.seconds[Q38_TM_QSA_INDEX]=0.6;
    profile.seconds[Q38_TM_QSA_ATTENTION]=0.7;
    profile.seconds[Q38_TM_LM_HEAD]=0.8;
    profile.forwards=4;
    char line[256];
    CHECK(q38_format_prof(line,sizeof line,2.0,7,3,&profile)>0);
    CHECK(!strcmp(line,"PROF 2.000 7 3 0.100 0.300 0.700 1.800 0.800 4\n"));
    volatile size_t short_capacity=8;
    CHECK(q38_format_prof(line,short_capacity,2.0,7,3,&profile)<0);

    puts("qwen38 metrics: request deltas, TPOT rate, PROF schema: ok");
    return 0;
}

int mbedtls_ccm_finish(mbedtls_ccm_context *ctx,
                       unsigned char *tag, size_t tag_len)
{
    int ret = MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    unsigned char i;

    if (ctx->state & CCM_STATE__ERROR) {
        return MBEDTLS_ERR_ERROR_CORRUPTION_DETECTED;
    }

    if (!(ctx->state & CCM_STATE__STARTED)) {
        return MBEDTLS_ERR_CCM_BAD_INPUT;
    }

    if (!(ctx->state & CCM_STATE__LENGTHS_SET)) {
        return MBEDTLS_ERR_CCM_BAD_INPUT;
    }

    if (ctx->add_len > 0 && !(ctx->state & CCM_STATE__AUTH_DATA_FINISHED)) {
        return MBEDTLS_ERR_CCM_BAD_INPUT;
    }

    if (ctx->plaintext_len > 0 && ctx->processed != ctx->plaintext_len) {
        return MBEDTLS_ERR_CCM_BAD_INPUT;
    }

    if (tag_len != ctx->tag_len) {
        return MBEDTLS_ERR_CCM_BAD_INPUT;
    }

    /*
     * Authentication: reset counter and crypt/mask internal tag
     */
    for (i = 0; i < ctx->q; i++) {
        ctx->ctr[15-i] = 0;
    }

    ret = mbedtls_ccm_crypt(ctx, 0, 16, ctx->y, ctx->y);
    if (ret != 0) {
        return ret;
    }
    if (tag != NULL) {
        memcpy(tag, ctx->y, tag_len);
    }
    mbedtls_ccm_clear_state(ctx);

    return 0;
}

ste_tok_decode1(const waste_tok *t, int32_t id, char *buf, int cap)
{
    for (int i = 0; i < t->n_tokens; i++)
        if (t->by_rank[i].rank == id) {
            const int l = t->by_rank[i].len < cap ? t->by_rank[i].len : cap;
            memcpy(buf, t->by_rank[i].p, (size_t)l);
            return l;
        }
    return 0;
}

