static void
test_wasm_runtime_aligned_alloc_zero_alignment(void **state)
{
    RuntimeInitArgs init_args;
    void *ptr;

    memset(&init_args, 0, sizeof(RuntimeInitArgs));
    init_args.mem_alloc_type = Alloc_With_Pool;
    init_args.mem_alloc_option.pool.heap_buf = malloc(256 * 1024);
    init_args.mem_alloc_option.pool.heap_size = 256 * 1024;

    assert_true(wasm_runtime_full_init(&init_args));

    /* Zero alignment should return NULL */
    ptr = wasm_runtime_aligned_alloc(128, 0);
    assert_null(ptr);

    wasm_runtime_destroy();
    free(init_args.mem_alloc_option.pool.heap_buf);
}

static void code_emit(code_builder_t *builder, const void *bytes,
                      size_t size) {
    assert(size <= sizeof(builder->bytes) - builder->size);
    memcpy(builder->bytes + builder->size, bytes, size);
    builder->size += (uint32_t) size;
}

psa_status_t psa_parse_key_data_from_storage(const uint8_t *storage_data,
                                             size_t storage_data_length,
                                             uint8_t **key_data,
                                             size_t *key_data_length,
                                             psa_key_attributes_t *attr)
{
    psa_status_t status;
    const psa_persistent_key_storage_format *storage_format =
        (const psa_persistent_key_storage_format *) storage_data;
    uint32_t version;

    if (storage_data_length < sizeof(*storage_format)) {
        return PSA_ERROR_DATA_INVALID;
    }

    status = check_magic_header(storage_data);
    if (status != PSA_SUCCESS) {
        return status;
    }

    version = MBEDTLS_GET_UINT32_LE(storage_format->version, 0);
    if (version != 0) {
        return PSA_ERROR_DATA_INVALID;
    }

    *key_data_length = MBEDTLS_GET_UINT32_LE(storage_format->data_len, 0);
    if (*key_data_length > (storage_data_length - sizeof(*storage_format)) ||
        *key_data_length > PSA_CRYPTO_MAX_STORAGE_SIZE) {
        return PSA_ERROR_DATA_INVALID;
    }

    if (*key_data_length == 0) {
        *key_data = NULL;
    } else {
        *key_data = mbedtls_calloc(1, *key_data_length);
        if (*key_data == NULL) {
            return PSA_ERROR_INSUFFICIENT_MEMORY;
        }
        memcpy(*key_data, storage_format->key_data, *key_data_length);
    }

    attr->lifetime = MBEDTLS_GET_UINT32_LE(storage_format->lifetime, 0);
    attr->type = MBEDTLS_GET_UINT16_LE(storage_format->type, 0);
    attr->bits = MBEDTLS_GET_UINT16_LE(storage_format->bits, 0);
    attr->policy.usage = MBEDTLS_GET_UINT32_LE(storage_format->policy, 0);
    attr->policy.alg = MBEDTLS_GET_UINT32_LE(storage_format->policy, sizeof(uint32_t));
    attr->policy.alg2 = MBEDTLS_GET_UINT32_LE(storage_format->policy, 2 * sizeof(uint32_t));

    return PSA_SUCCESS;
}

id mf_plus_crypto_cmac(
    const uint8_t key[MF_PLUS_AES_KEY_SIZE],
    const uint8_t* data,
    size_t length,
    uint8_t mac[MF_PLUS_AES_BLOCK_SIZE]) {
    uint8_t k1[MF_PLUS_AES_BLOCK_SIZE], k2[MF_PLUS_AES_BLOCK_SIZE];
    mf_plus_crypto_cmac_subkeys(key, k1, k2);

    size_t n = (length + MF_PLUS_AES_BLOCK_SIZE - 1) / MF_PLUS_AES_BLOCK_SIZE;
    if(n == 0) n = 1;
    const bool last_complete = (length > 0) && (length % MF_PLUS_AES_BLOCK_SIZE == 0);

    uint8_t x[MF_PLUS_AES_BLOCK_SIZE];
    memset(x, 0, sizeof(x));

    for(size_t i = 0; i < n - 1; i++) {
        uint8_t y[MF_PLUS_AES_BLOCK_SIZE];
        for(size_t j = 0; j < MF_PLUS_AES_BLOCK_SIZE; j++) {
            y[j] = x[j] ^ data[i * MF_PLUS_AES_BLOCK_SIZE + j];
        }
        mf_plus_crypto_ecb_encrypt(key, y, x);
    }

    uint8_t last[MF_PLUS_AES_BLOCK_SIZE];
    const size_t offset = (n - 1) * MF_PLUS_AES_BLOCK_SIZE;
    if(last_complete) {
        for(size_t j = 0; j < MF_PLUS_AES_BLOCK_SIZE; j++) {
            last[j] = data[offset + j] ^ k1[j];
        }
    } else {
        memset(last, 0, sizeof(last));
        const size_t rem = length - offset;
        memcpy(last, &data[offset], rem);
        last[rem] = 0x80;
        for(size_t j = 0; j < MF_PLUS_AES_BLOCK_SIZE; j++) {
            last[j] ^= k2[j];
        }
    }

    uint8_t y[MF_PLUS_AES_BLOCK_SIZE];
    for(size_t j = 0; j < MF_PLUS_AES_BLOCK_SIZE; j++) {
        y[j] = x[j] ^ last[j];
    }
    mf_plus_crypto_ecb_encrypt(key, y, mac);
}

static NTSTATUS
_bpf2c_query_npi_module_id(
    _In_ const wchar_t* value_name,
    unsigned long value_type,
    _In_ const void* value_data,
    unsigned long value_length,
    _Inout_ void* context,
    _Inout_ void* entry_context)
{
    UNREFERENCED_PARAMETER(value_name);
    UNREFERENCED_PARAMETER(context);
    UNREFERENCED_PARAMETER(entry_context);

    if (value_type != REG_BINARY) {
        return STATUS_INVALID_PARAMETER;
    }
    if (value_length != sizeof(_bpf2c_module_id.Guid)) {
        return STATUS_INVALID_PARAMETER;
    }

    memcpy(&_bpf2c_module_id.Guid, value_data, value_length);
    return STATUS_SUCCESS;
}

