static uint8_t *make_riscv_align_object(bool corrupt_padding,
                                        size_t *result_size) {
    static const char symbol_names[] = "\0_start\0target";
    static const uint8_t text_bytes[] = {
            0x01U,
            0x00U,
            0x00U,
            0x00U,
            0x00U,
            0x00U,
    };
    const size_t text_offset = LD_ELF64_EHDR_SIZE;
    const size_t rela_offset = test_elf_align(
            text_offset + sizeof(text_bytes), 8U);
    const size_t relocation_count = 2U;
    const size_t symbols_offset =
            rela_offset + relocation_count * LD_ELF64_RELA_SIZE;
    const size_t symbol_count = 4U;
    const size_t strings_offset =
            symbols_offset + symbol_count * LD_ELF64_SYM_SIZE;

    char section_names[96] = {0};
    size_t section_names_size = 1U;
    uint32_t text_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".text");
    uint32_t rela_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".rela.text");
    uint32_t symtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".symtab");
    uint32_t strtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".strtab");
    uint32_t shstrtab_name = test_elf_append_name(
            section_names, sizeof(section_names), &section_names_size,
            ".shstrtab");
    const size_t section_names_offset =
            strings_offset + sizeof(symbol_names);
    const size_t section_table_offset = test_elf_align(
            section_names_offset + section_names_size, 8U);
    const uint16_t section_count = 6U;
    const size_t size = section_table_offset +
                        (size_t) section_count * LD_ELF64_SHDR_SIZE;
    uint8_t *bytes = calloc(1, size);
    assert(bytes != NULL);

    bytes[0] = LD_ELF_MAGIC_0;
    bytes[1] = LD_ELF_MAGIC_1;
    bytes[2] = LD_ELF_MAGIC_2;
    bytes[3] = LD_ELF_MAGIC_3;
    bytes[LD_ELF_EI_CLASS] = LD_ELF_CLASS_64;
    bytes[LD_ELF_EI_DATA] = LD_ELF_DATA_LSB;
    bytes[LD_ELF_EI_VERSION] = LD_ELF_VERSION_CURRENT;
    test_elf_write_u16(bytes + 16U, LD_ELF_ET_REL);
    test_elf_write_u16(bytes + 18U, LD_ELF_EM_RISCV);
    test_elf_write_u32(bytes + 20U, LD_ELF_VERSION_CURRENT);
    test_elf_write_u32(bytes + 48U, 1U); /* EF_RISCV_RVC */
    test_elf_write_u64(bytes + 40U, section_table_offset);
    test_elf_write_u16(bytes + 52U, LD_ELF64_EHDR_SIZE);
    test_elf_write_u16(bytes + 58U, LD_ELF64_SHDR_SIZE);
    test_elf_write_u16(bytes + 60U, section_count);
    test_elf_write_u16(bytes + 62U, 5U);

    memcpy(bytes + text_offset, text_bytes, sizeof(text_bytes));
    if (corrupt_padding) bytes[text_offset] = 0xffU;
    memcpy(bytes + strings_offset, symbol_names, sizeof(symbol_names));
    memcpy(bytes + section_names_offset, section_names,
           section_names_size);

    uint8_t *relocation = bytes + rela_offset;
    test_elf_write_u64(relocation, 0U);
    test_elf_write_u64(
            relocation + 8U,
            LD_ELF_RELA_INFO(0U, LD_ELF_R_RISCV_ALIGN));
    test_elf_write_u64(relocation + 16U, 2U);
    relocation += LD_ELF64_RELA_SIZE;
    test_elf_write_u64(relocation, 2U);
    test_elf_write_u64(
            relocation + 8U,
            LD_ELF_RELA_INFO(1U, LD_ELF_R_RISCV_32));
    test_elf_write_u64(relocation + 16U, 6U);

    uint8_t *symbols = bytes + symbols_offset;
    uint8_t *section_symbol = symbols + LD_ELF64_SYM_SIZE;
    section_symbol[4] =
            LD_ELF_SYM_INFO(LD_ELF_STB_LOCAL, LD_ELF_STT_SECTION);
    test_elf_write_u16(section_symbol + 6U, 1U);
    uint8_t *start = section_symbol + LD_ELF64_SYM_SIZE;
    test_elf_write_u32(start, 1U);
    start[4] = LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_FUNC);
    test_elf_write_u16(start + 6U, 1U);
    test_elf_write_u64(start + 8U, 2U);
    test_elf_write_u64(start + 16U, 4U);
    uint8_t *target = start + LD_ELF64_SYM_SIZE;
    test_elf_write_u32(target, 8U);
    target[4] = LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_NOTYPE);
    test_elf_write_u16(target + 6U, 1U);
    test_elf_write_u64(target + 8U, 6U);

    uint8_t *sections = bytes + section_table_offset;
    test_elf_write_section(
            sections + LD_ELF64_SHDR_SIZE, text_name,
            LD_ELF_SHT_PROGBITS,
            LD_ELF_SHF_ALLOC | LD_ELF_SHF_EXECINSTR, text_offset,
            sizeof(text_bytes), 0U, 0U, 4U, 0U);
    test_elf_write_section(
            sections + 2U * LD_ELF64_SHDR_SIZE, rela_name,
            LD_ELF_SHT_RELA, 0U, rela_offset,
            relocation_count * LD_ELF64_RELA_SIZE, 3U, 1U, 8U,
            LD_ELF64_RELA_SIZE);
    test_elf_write_section(
            sections + 3U * LD_ELF64_SHDR_SIZE, symtab_name,
            LD_ELF_SHT_SYMTAB, 0U, symbols_offset,
            symbol_count * LD_ELF64_SYM_SIZE, 4U, 2U, 8U,
            LD_ELF64_SYM_SIZE);
    test_elf_write_section(
            sections + 4U * LD_ELF64_SHDR_SIZE, strtab_name,
            LD_ELF_SHT_STRTAB, 0U, strings_offset, sizeof(symbol_names),
            0U, 0U, 1U, 0U);
    test_elf_write_section(
            sections + 5U * LD_ELF64_SHDR_SIZE, shstrtab_name,
            LD_ELF_SHT_STRTAB, 0U, section_names_offset,
            section_names_size, 0U, 0U, 1U, 0U);

    *result_size = size;
    return bytes;
}

static void emit_peobj_sym(BuildCtx *ctx, const char *name, uint32_t value,
			   int sect, int type, int scl)
{
  PEsym sym;
  size_t len = strlen(name);
  if (!strtab) {  /* Pass 1: only calculate string table length. */
    if (len > 8) strtabofs += len+1;
    return;
  }
  if (len <= 8) {
    memcpy(sym.n.name, name, len);
    memset(sym.n.name+len, 0, 8-len);
  } else {
    sym.n.nameref[0] = 0;
    sym.n.nameref[1] = (uint32_t)strtabofs;
    memcpy(strtab + strtabofs, name, len);
    strtab[strtabofs+len] = 0;
    strtabofs += len+1;
  }
  sym.value = value;
  sym.sect = (int16_t)(sect+1);  /* 1-based section number. */
  sym.type = (uint16_t)type;
  sym.scl = (uint8_t)scl;
  sym.naux = 0;
  owrite(ctx, &sym, PEOBJ_SYM_SIZE);
}

static int sendfd(int sockfd, int fd)
{
	struct msghdr msg = {};
	struct cmsghdr *cmsg;
	int fds[1] = { fd };
	char iobuf[1] = { 0 };
	struct iovec io = {
		.iov_base = iobuf,
		.iov_len = sizeof(iobuf),
	};
	union {
		char buf[CMSG_SPACE(sizeof(fds))];
		struct cmsghdr align;
	} u = {};
	ssize_t ret;

	msg.msg_iov = &io;
	msg.msg_iovlen = 1;
	msg.msg_control = u.buf;
	msg.msg_controllen = sizeof(u.buf);

	cmsg = CMSG_FIRSTHDR(&msg);
	cmsg->cmsg_level = SOL_SOCKET;
	cmsg->cmsg_type = SCM_RIGHTS;
	cmsg->cmsg_len = CMSG_LEN(sizeof(fds));
	memcpy(CMSG_DATA(cmsg), fds, sizeof(fds));

	ret = sendmsg(sockfd, &msg, 0);
	if (ret < 0)
		return -errno;
	if (ret != 1)
		return -EIO;

	return 0;
}

const char* get_default_route_interface(){

    static char iface[64];
    FILE *fp;

    iface[0] = '\0';

    if ((fp = popen("ip -o route show default 2>/dev/null | awk '{print $5; exit}'", "r")) == NULL) {
        printf("Error opening pipe!\n");
        return NULL;
    }

    if (fgets(iface, sizeof(iface), fp) != NULL)
        iface[strcspn(iface, "\n")] = '\0';

    pclose(fp);

    return iface[0] != '\0' ? iface : NULL;
}

static void append_custom_headers(buff_struct *bstr, const char *headers) {
  const size_t base = bstr->pos;
  hts_boolean keep = HTS_TRUE;
  const char *line;

  for (line = headers; *line != '\0';) {
    const char *eol = line;
    const char *next;

    while (*eol != '\0' && *eol != '\r' && *eol != '\n')
      eol++;
    next = eol;
    if (next[0] == '\r' && next[1] == '\n')
      next += 2;
    else if (*next != '\0')
      next++;

    if (*line != ' ' && *line != '\t') { /* not a folded continuation */
      const char *colon = line;
      char field[128];

      keep = HTS_TRUE;
      while (colon < eol && *colon != ':')
        colon++;
      if (colon > line && colon < eol &&
          (size_t) (colon - line) < sizeof(field)) {
        const size_t len = (size_t) (colon - line);
        const char cut = bstr->buffer[base];

        memcpy(field, line, len);
        field[len] = '\0';
        /* only what the engine wrote, so the box may repeat its own fields */
        bstr->buffer[base] = '\0';
        keep = !http_headers_have_field(bstr->buffer, field);
        bstr->buffer[base] = cut;
      }
    }
    if (keep)
      print_buffer(bstr, "%.*s", (int) (next - line), line);
    line = next;
  }
}

void mf_plus_merge_update(MfPlusData* base, const MfPlusData* fresh) {
    furi_check(base);
    furi_check(fresh);

    // Per-field overlay: copy only what `fresh` actually recovered, never clearing a field `base`
    // already had (see mf_plus.h for why a successful re-read can still come back with less).
    for(uint16_t block = 0; block < MF_PLUS_MAX_BLOCKS; block++) {
        if(mf_plus_is_block_read(fresh, block)) {
            mf_plus_set_block_read(base, block, &fresh->block[block]);
        }
    }
    for(uint8_t sector = 0; sector < MF_PLUS_MAX_SECTORS; sector++) {
        if(mf_plus_is_key_found(fresh, sector, MfPlusKeyTypeA)) {
            mf_plus_set_key_found(base, sector, MfPlusKeyTypeA, &fresh->key_a[sector]);
        }
        if(mf_plus_is_key_found(fresh, sector, MfPlusKeyTypeB)) {
            mf_plus_set_key_found(base, sector, MfPlusKeyTypeB, &fresh->key_b[sector]);
        }
    }
    for(uint8_t type = 0; type < MfPlusAdminKeyNum; type++) {
        if(mf_plus_is_admin_key_found(fresh, type)) {
            mf_plus_set_admin_key_found(base, type, &fresh->admin_key[type]);
        }
    }
    for(uint8_t index = 0; index < MF_PLUS_CONFIG_BLOCK_NUM; index++) {
        if(mf_plus_is_config_block_read(fresh, index)) {
            mf_plus_set_config_block_read(base, index, &fresh->config_block[index]);
        }
    }
    if(fresh->signature_present) {
        memcpy(base->signature, fresh->signature, MF_PLUS_SIGNATURE_SIZE);
        base->signature_present = true;
    }
}

static void jstr_field(const char *js, const char *key, int idx,
                       char *out, size_t cap)
{
    out[0] = 0;
    const char *k = strstr(js, key);
    if (!k) return;
    const char *p = strchr(k + strlen(key), '[');
    if (!p) return;
    for (int i = 0; i <= idx; i++) {
        p = strchr(p, '"');
        if (!p) return;
        if (i < idx) { p = strchr(p + 1, '"'); if (!p) return; p++; }
    }
    p++;
    size_t n = 0;
    while (*p && *p != '"' && n + 1 < cap) {
        if (*p == '\\' && p[1]) {           /* \n and friends */
            p++;
            out[n++] = *p == 'n' ? '\n' : *p == 't' ? '\t' : *p;
        } else out[n++] = *p;
        p++;
    }
    out[n] = 0;
}

psa_status_t p256_transparent_import_key(const psa_key_attributes_t *attributes,
                             const uint8_t *data,
                             size_t data_length,
                             uint8_t *key_buffer,
                             size_t key_buffer_size,
                             size_t *key_buffer_length,
                             size_t *bits)
{
    /* Check the key size */
    if (*bits != 0 && *bits != CURVE_BITS) {
        return PSA_ERROR_NOT_SUPPORTED;
    }

    /* Validate the key (and its type and size) */
    psa_key_type_t type = psa_get_key_type(attributes);
    if (type == PSA_KEY_TYPE_ECC_PUBLIC_KEY(PSA_ECC_FAMILY_SECP_R1)) {
        if (data_length != PSA_PUBKEY_SIZE) {
            return *bits == 0 ? PSA_ERROR_NOT_SUPPORTED : PSA_ERROR_INVALID_ARGUMENT;
        }
        /* See INFORMATION ON PSA KEY EXPORT FORMATS near top of file */
        if (p256_validate_pubkey(data + 1) != P256_SUCCESS) {
            return PSA_ERROR_INVALID_ARGUMENT;
        }
    } else if (type == PSA_KEY_TYPE_ECC_KEY_PAIR(PSA_ECC_FAMILY_SECP_R1)) {
        if (data_length != PRIVKEY_SIZE) {
            return *bits == 0 ? PSA_ERROR_NOT_SUPPORTED : PSA_ERROR_INVALID_ARGUMENT;
        }
        if (p256_validate_privkey(data) != P256_SUCCESS) {
            return PSA_ERROR_INVALID_ARGUMENT;
        }
    } else {
        return PSA_ERROR_NOT_SUPPORTED;
    }
    *bits = CURVE_BITS;

    /* We only support the export format for input, so just copy. */
    if (key_buffer_size < data_length) {
        return PSA_ERROR_BUFFER_TOO_SMALL;
    }
    memcpy(key_buffer, data, data_length);
    *key_buffer_length = data_length;

    return PSA_SUCCESS;
}

void CTracer::operator()(const wchar_t *sLine, ...) const
{
	const size_t bufferSize = 10241;
	wchar_t bufferline[bufferSize];

	va_list argptr;
	va_start(argptr, sLine);
#ifndef WIN32
	if (vswprintf_l(bufferline, bufferSize, sLine, argptr) == -1)
#else
	if (vswprintf(bufferline, bufferSize, sLine, argptr) == -1)
#endif
		bufferline[bufferSize - 1] = L'\0';
	va_end(argptr);

	QString sBufferLine = QString::fromWCharArray(bufferline);
	qDebug() << sBufferLine;
}

