static char *lcui_settings_get_config_root(void)
{
#ifdef _WIN32
        const char *base = getenv("APPDATA");
        if (base && base[0] != 0) {
                return lcui_strdup(base);
        }
        base = getenv("USERPROFILE");
        if (base && base[0] != 0) {
                return lcui_join_path(base, "AppData/Roaming");
        }
#elif defined(__APPLE__)
        const char *base = getenv("HOME");
        if (base && base[0] != 0) {
                return lcui_join_path(base, "Library/Application Support");
        }
#else
        const char *base = getenv("XDG_CONFIG_HOME");
        if (base && base[0] != 0) {
                return lcui_strdup(base);
        }
        base = getenv("HOME");
        if (base && base[0] != 0) {
                return lcui_join_path(base, ".config");
        }
#endif
        return NULL;
}

static void
test_wasm_runtime_aligned_alloc_valid(void **state)
{
    RuntimeInitArgs init_args;
    void *ptr;

    memset(&init_args, 0, sizeof(RuntimeInitArgs));
    init_args.mem_alloc_type = Alloc_With_Pool;
    init_args.mem_alloc_option.pool.heap_buf = malloc(256 * 1024);
    init_args.mem_alloc_option.pool.heap_size = 256 * 1024;

    assert_true(wasm_runtime_full_init(&init_args));

    /* Test valid aligned allocation */
    ptr = wasm_runtime_aligned_alloc(128, 64);
    assert_non_null(ptr);
    assert_true(is_aligned(ptr, 64));

    /* Free should work */
    wasm_runtime_free(ptr);

    wasm_runtime_destroy();
    free(init_args.mem_alloc_option.pool.heap_buf);
}

