int main(int argc, char **argv)
{
  BuildCtx ctx_;
  BuildCtx *ctx = &ctx_;
  int status, binmode;

  if (sizeof(void *) != 4*LJ_32+8*LJ_64) {
    fprintf(stderr,"Error: pointer size mismatch in cross-build.\n");
    fprintf(stderr,"Try: make HOST_CC=\"gcc -m32\" CROSS=...\n\n");
    return 1;
  }

  UNUSED(argc);
  parseargs(ctx, argv);

  if ((status = build_code(ctx))) {
    fprintf(stderr,"Error: DASM error %08x\n", status);
    return 1;
  }

  switch (ctx->mode) {
  case BUILD_peobj:
  case BUILD_raw:
    binmode = 1;
    break;
  default:
    binmode = 0;
    break;
  }

  if (ctx->outname[0] == '-' && ctx->outname[1] == '\0') {
    ctx->fp = stdout;
#if defined(_WIN32)
    if (binmode)
      _setmode(_fileno(stdout), _O_BINARY);  /* Yuck. */
#endif
  } else if (!(ctx->fp = fopen(ctx->outname, binmode ? "wb" : "w"))) {
    fprintf(stderr, "Error: cannot open output file '%s': %s\n",
	    ctx->outname, strerror(errno));
    exit(1);
  }

  switch (ctx->mode) {
  case BUILD_elfasm:
  case BUILD_coffasm:
  case BUILD_machasm:
    emit_asm(ctx);
    emit_asm_debug(ctx);
    break;
  case BUILD_peobj:
    emit_peobj(ctx);
    break;
  case BUILD_raw:
    emit_raw(ctx);
    break;
  case BUILD_bcdef:
    emit_bcdef(ctx);
    emit_lib(ctx);
    break;
  case BUILD_vmdef:
    emit_vmdef(ctx);
    emit_lib(ctx);
    fprintf(ctx->fp, "}\n\n");
    break;
  case BUILD_ffdef:
  case BUILD_libdef:
  case BUILD_recdef:
    emit_lib(ctx);
    break;
  case BUILD_folddef:
    emit_fold(ctx);
    break;
  default:
    break;
  }

  fflush(ctx->fp);
  if (ferror(ctx->fp)) {
    fprintf(stderr, "Error: cannot write to output file: %s\n",
	    strerror(errno));
    exit(1);
  }
  fclose(ctx->fp);

  return 0;
}

int32_t network_ping_app(void* p) {
    UNUSED(p);

    PingApp* app = malloc(sizeof(PingApp));
    memset(app, 0, sizeof(PingApp));
    app->mutex = furi_mutex_alloc(FuriMutexTypeNormal);
    app->state = RunStateIdle;
    app->id_counter = CONNECTION_ID_BASE;

    FuriMessageQueue* event_queue = furi_message_queue_alloc(8, sizeof(InputEvent));
    Network* network = furi_record_open(RECORD_NETWORK);
    network_set_event_callback(network, ping_event_callback, app);

    ViewPort* view_port = view_port_alloc();
    view_port_draw_callback_set(view_port, ping_render_callback, app);
    view_port_input_callback_set(view_port, ping_input_callback, event_queue);

    Gui* gui = furi_record_open(RECORD_GUI);
    gui_add_view_port(gui, view_port, GuiLayerFullscreen);

    ping_start_run(app, network, ProbeModeDns);

    InputEvent event;
    for(bool processing = true; processing;) {
        if(furi_message_queue_get(event_queue, &event, 100) == FuriStatusOk &&
           event.type == InputTypeShort) {
            furi_mutex_acquire(app->mutex, FuriWaitForever);
            ProbeMode mode = app->mode;
            furi_mutex_release(app->mutex);

            if(event.key == InputKeyBack) {
                processing = false;
            } else if(event.key == InputKeyOk) {
                ping_start_run(app, network, mode);
            } else if(event.key == InputKeyLeft || event.key == InputKeyRight) {
                uint32_t step = event.key == InputKeyRight ? 1 : ProbeModeCount - 1;
                ping_start_run(app, network, (ProbeMode)((mode + step) % ProbeModeCount));
            }
        }

        ping_process(app, network);
        view_port_update(view_port);
    }

    furi_mutex_acquire(app->mutex, FuriWaitForever);
    if(app->socket_open || app->probe_active) {
        ping_push_close(app, app->cur_id);
        app->socket_open = false;
    }
    uint32_t close_count = app->close_count;
    uint32_t closes[COUNT_OF(app->close_ids)];
    memcpy(closes, app->close_ids, close_count * sizeof(uint32_t));
    app->close_count = 0;
    furi_mutex_release(app->mutex);
    for(uint32_t i = 0; i < close_count; i++) {
        network_close(network, closes[i]);
    }

    /* Unsubscribe before closing the record so late events cannot reach a
     * freed context. */
    network_set_event_callback(network, NULL, NULL);
    furi_record_close(RECORD_NETWORK);

    view_port_enabled_set(view_port, false);
    gui_remove_view_port(gui, view_port);
    furi_record_close(RECORD_GUI);
    view_port_free(view_port);
    furi_message_queue_free(event_queue);
    furi_mutex_free(app->mutex);
    free(app);

    return 0;
}

static int halUnaryKernel(const void* src0_, size_t s0y, size_t s0x,
                          const void*, size_t, size_t, const void*, size_t, size_t,
                          void* dst_, size_t dsty, int width, int height,
                          const double*, int, void* userdata)
{
    typedef int (*HalFunc)(const T*, T*, int);
    const HalFunc fn = (HalFunc)userdata;
    s0y /= sizeof(T);
    dsty /= sizeof(T);
    CV_Assert(s0x <= 1u);
    const T* src0 = (const T*)src0_;
    T* dst = (T*)dst_;
    if (height > 1 && dsty == (size_t)width && s0y == s0x*(size_t)width) { width *= height; height = 1; }
    const int urows = (s0y == 0 && height > 1) ? 1 : height;   // vertical broadcast: 1 row + copies
    for (int y = 0; y < urows; y++, src0 += s0y, dst += dsty)
    {
        int code;
        if (s0x == 0)                     // broadcast-scalar source: one value covers the row
        {
            T v;
            code = fn(src0, &v, 1);
            for (int x = 0; x < width; x++) dst[x] = v;
        }
        else
            code = fn(src0, dst, width);
        if (code != CV_HAL_ERROR_OK)
            return code;                  // shouldn't happen (probed at get time) - let exec assert
    }
    dst = (T*)dst_;
    for (int y = urows; y < height; y++)
        memcpy(dst + (size_t)y*dsty, dst, (size_t)width*sizeof(T));
    return 0;
}

static int cmd_plan(int argc, char **argv)
{
    if (argc < 3) { fprintf(stderr, "usage: waste plan MODEL [--budget N] [--ctx N]\n"); return 2; }
    opts o; opts_init(&o);
    if (parse_opts(argc, argv, 3, &o)) return 2;

    waste_memplan p;
    const waste_status st = waste_plan_memory(argv[2], o.ctx, &p);
    if (st != WASTE_OK) return fail("plan", st);

    char b[5][32];
    human(p.trunk_bytes, b[0], 32); human(p.state_bytes, b[1], 32);
    human(p.scratch_bytes, b[2], 32); human(p.min_expert_cache, b[3], 32);
    human(p.floor_bytes, b[4], 32);
    printf("memory plan for %s (ctx %u)\n\n", argv[2], o.ctx);
    printf("  resident trunk        %12s\n", b[0]);
    printf("  KDA state + KV cache  %12s\n", b[1]);
    printf("  scratch               %12s\n", b[2]);
    printf("  minimum expert cache  %12s\n", b[3]);
    printf("  ---------------------------------\n");
    printf("  FLOOR                 %12s\n", b[4]);
    human(p.recommended_bytes, b[0], 32);
    printf("  recommended           %12s   (floor + 3x a token's working set;\n"
           "                                      below that the cache keeps\n"
           "                                      nothing alive between tokens)\n", b[0]);
    if (o.budget) {
        char bb[32];
        human(o.budget, bb, 32);
        if (o.budget < p.floor_bytes) printf("\n  budget %s is BELOW the floor — open would fail\n", bb);
        else {
            char cb[32];
            human(o.budget - p.floor_bytes + p.min_expert_cache, cb, 32);
            printf("\n  budget %s -> expert cache %s\n", bb, cb);
        }
    }
    return 0;
}

