static void coff_encode_aux_record(const coff_aux_record_t *aux,
                                   uint8_t bytes[LD_COFF_SYMBOL_SIZE]) {
    memset(bytes, 0, LD_COFF_SYMBOL_SIZE);
    switch (aux->kind) {
        case COFF_AUX_RAW:
            memcpy(bytes, aux->value.raw, LD_COFF_SYMBOL_SIZE);
            break;
        case COFF_AUX_SECTION_DEFINITION: {
            const coff_section_t *section =
                    aux->value.section_definition.section;
            coff_write_u32(bytes, section->logical_size);
            const uint16_t relocation_count =
                    section->relocation_count >= UINT16_MAX
                            ? UINT16_MAX
                            : (uint16_t) section->relocation_count;
            coff_write_u16(bytes + 4U, relocation_count);
            coff_write_u16(bytes + 6U, 0U);
            coff_write_u32(bytes + 8U,
                           aux->value.section_definition.checksum);
            uint32_t number = 0U;
            if (aux->value.section_definition.associative_parent)
                number = aux->value.section_definition.associative_parent
                                 ->index;
            coff_write_u16(bytes + 12U, (uint16_t) number);
            bytes[14] = aux->value.section_definition.selection;
            bytes[15] = 0U;
            coff_write_u16(bytes + 16U, 0U);
            break;
        }
        case COFF_AUX_WEAK_EXTERNAL:
            coff_write_u32(
                    bytes,
                    aux->value.weak_external.fallback_symbol_index);
            coff_write_u32(bytes + 4U,
                           aux->value.weak_external.characteristics);
            break;
    }
}

static void test_sdk_appkit_objc_exports(void) {
    const char *sdkroot = getenv("SDKROOT");
    if (!sdkroot || !*sdkroot) return;
    char appkit_path[4096];
    int path_length = snprintf(appkit_path, sizeof(appkit_path),
                               "%s/System/Library/Frameworks/AppKit.framework/AppKit.tbd", sdkroot);
    if (path_length < 0 || (size_t) path_length >= sizeof(appkit_path) || access(appkit_path, R_OK) != 0) {
        return;
    }

    ld_options_t options;
    ld_options_init(&options);
    ld_context_t ctx = {0};
    ctx.options = &options;
    assert(ld_parse_input_file(&ctx, appkit_path) == LD_OK);
    assert(ctx.dylibs.count == 1U);
    const ld_dylib_input_t *appkit = &ctx.dylibs.items[0];
    assert(test_ld_dylib_has_symbol(appkit->exports, appkit->export_count,
                                    "_OBJC_CLASS_$_NSApplication"));
    assert(test_ld_dylib_has_symbol(appkit->exports, appkit->export_count,
                                    "_OBJC_METACLASS_$_NSApplication"));
    test_ld_parsed_context_deinit(&ctx);
    ld_options_deinit(&options);
}

static int serialize_io_to_buf_r(IoState *state, IoObject *obj, unsigned char *buf, int maxLen,
                                  IoObject **visited, int *visitedCount) {
	if (ioUndefined && obj == ioUndefined) {
		buf[0] = TYPE_UNDEFINED;
		return 1;
	}

		UArray *uarray = IoSeq_rawUArray(obj);
		// Numeric sequence (Vector) → TypedArray
		if (uarray->encoding == CENCODING_NUMBER) {
			int wt = ctype_to_wire_itemtype(uarray->itemType);
			if (wt < 0) goto seq_as_string; // unsupported type, fall through to string
			int count = (int)uarray->size;
			int byteLen = count * uarray->itemSize;
			if (maxLen < 6 + byteLen) return 0;
			buf[0] = TYPE_TYPEDARRAY;
			buf[1] = (unsigned char)wt;
			memcpy(buf + 2, &count, 4);
			memcpy(buf + 6, uarray->data, byteLen);
			return 6 + byteLen;
		}
	seq_as_string:;
		// Cycle detection for containers
		for (int i = 0; i < *visitedCount; i++) {
