static void test_elf_unreferenced_ifunc_definition(void) {
    size_t object_size;
    uint8_t *object =
            make_test_elf_object(LD_ELF_EM_X86_64, false, false,
                                 &object_size);
    size_t section_table_offset = (size_t) test_elf_read_u64(object + 40U);
    assert(section_table_offset <= object_size &&
           3U * LD_ELF64_SHDR_SIZE <= object_size - section_table_offset);
    const uint8_t *symbol_section =
            object + section_table_offset + 2U * LD_ELF64_SHDR_SIZE;
    size_t symbol_table_offset =
            (size_t) test_elf_read_u64(symbol_section + 24U);
    assert(symbol_table_offset <= object_size - 2U * LD_ELF64_SYM_SIZE);
    uint8_t *start_symbol =
            object + symbol_table_offset + LD_ELF64_SYM_SIZE;
    start_symbol[4] =
            LD_ELF_SYM_INFO(LD_ELF_STB_GLOBAL, LD_ELF_STT_GNU_IFUNC);

    char object_path[] = "/tmp/nature-ld-ifunc-XXXXXX";
    write_fixture(object_path, object, object_size);
    free(object);
    static const char *output_path = "/tmp/nature-ld-ifunc-output";
    unlink(output_path);

    diagnostic_capture_t capture = {0};
    ld_options_t options;
    ld_options_init(&options);
    options.os = LD_OS_LINUX;
    options.arch = LD_ARCH_AMD64;
    options.output_path = output_path;
    options.entry_symbol = "_start";
    options.pie = false;
    options.adhoc_codesign = false;
    options.diagnostic = capture_diagnostic;
    options.diagnostic_context = &capture;
    assert(ld_add_input(&options, object_path) == LD_OK);
    assert(ld_link_elf(&options) == LD_OK);
    assert(capture.count == 0U);
    assert(access(output_path, X_OK) == 0);

    size_t image_size;
    uint8_t *image = read_test_fixture(output_path, &image_size, NULL);
    assert(test_elf_find_output_section(image, image_size, ".plt.got") ==
           NULL);
    assert(test_elf_find_output_section(image, image_size, ".rela.dyn") ==
           NULL);
    free(image);

    ld_options_deinit(&options);
    unlink(object_path);
    unlink(output_path);
}

void flb_test_file_rotation_mkdir(void)
{
    int i;
    int ret;
    int bytes;
    char *p = (char *)JSON_SMALL;
    flb_ctx_t *ctx;
    int in_ffd;
    int out_ffd;
    FILE *fp;
    char logfile[PATH_MAX];
    char nested_path[PATH_MAX];
    struct stat st;

    snprintf(nested_path, sizeof(nested_path),
             "%s" PATH_SEPARATOR "nested" PATH_SEPARATOR "deep" PATH_SEPARATOR
             "path",
             TEST_LOGPATH);
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wformat-truncation"
    snprintf(logfile, sizeof(logfile), "%s" PATH_SEPARATOR "test_mkdir.log",
             nested_path);
#pragma GCC diagnostic pop

    recursive_delete_directory(TEST_LOGPATH);

    ctx = flb_create();
    TEST_ASSERT(flb_service_set(ctx, "Flush", "1", "Grace", "1", "Log_Level",
                                "error", NULL) == 0);

    in_ffd = flb_input(ctx, (char *)"lib", NULL);
    TEST_CHECK(in_ffd >= 0);
    flb_input_set(ctx, in_ffd, "tag", "test", NULL);

    out_ffd = flb_output(ctx, (char *)"file", NULL);
    TEST_CHECK(out_ffd >= 0);
    TEST_ASSERT(flb_output_set(ctx, out_ffd, "match", "test", "file", logfile,
                               "mkdir", "true", "rotate", "true",
                               "rotate_max_size", "100M", "rotate_gzip",
                               "false", NULL) == 0);

    ret = flb_start(ctx);
    TEST_CHECK(ret == 0);

    for (i = 0; i < 3; i++) {
        bytes = flb_lib_push(ctx, in_ffd, p, strlen(p));
        TEST_CHECK(bytes == strlen(p));
    }

    flb_time_msleep(1500);

    flb_stop(ctx);
    flb_destroy(ctx);

    TEST_CHECK(stat(nested_path, &st) == 0);
    TEST_CHECK(S_ISDIR(st.st_mode));

    fp = fopen(logfile, "r");
    TEST_CHECK(fp != NULL);
    if (fp) {
        fclose(fp);
    }

    recursive_delete_directory(TEST_LOGPATH);
}

int cliRecord(const char ** argv)
{
  if (!argv[1] || !argv[1][0]) {
    cliSerialPrint("%s: missing filename", argv[0]);
    return 0;
  }

  int seconds = 5;
  if (argv[2] && argv[2][0]) {
    if (toInt(argv, 2, &seconds) == 0 || seconds <= 0 || seconds > 600) {
      cliSerialPrint("%s: Invalid duration \"%s\"", argv[0], argv[2]);
      return 0;
    }
  }

  char pathBuf[64];
  const char* path = argv[1];
  const size_t nameLen = strlen(argv[1]);
  const bool hasExt =
      nameLen >= 4 && strcasecmp(argv[1] + nameLen - 4, ".wav") == 0;
  if (!hasExt) {
    if (nameLen + 5 > sizeof(pathBuf)) {
      cliSerialPrint("%s: path too long", argv[0]);
      return 0;
    }
    memcpy(pathBuf, argv[1], nameLen);
    memcpy(pathBuf + nameLen, ".wav", 5);
    path = pathBuf;
  }

  const uint32_t totalSamples = PdmWavRecorder::DST_RATE * (uint32_t)seconds;
  // Capture only runs while needed — bring the hardware up for this command.
  pdmStart();
  PdmWavRecorder rec;
  FRESULT res = rec.start(path, (uint32_t)seconds);
  if (res != FR_OK) {
    pdmStop();
    cliSerialPrint("%s: cannot open \"%s\" (err %u)", argv[0], path,
                   (unsigned)res);
    return 0;
  }

  cliSerialPrint("Recording %d s (%u samples @ %u Hz) to %s",
                 seconds, (unsigned)totalSamples,
                 (unsigned)PdmWavRecorder::DST_RATE, path);

  while (rec.isRecording() && rec.getSamplesWritten() < totalSamples) {
    sleep_ms(50);
  }

  rec.stop();
  pdmStop();
  cliSerialPrint("Recorded %u samples (%u bytes)",
                 (unsigned)rec.getSamplesWritten(),
                 (unsigned)rec.getBytesWritten());
  return 0;
}
