void cache_keep_previous(httrackp *opt, cache_back *cache, const char *url_adr,
                         const char *url_fil, const char *url_save) {
  char BIGSTK previous_save[HTS_URLMAXSIZE * 2];
  htsblk r;

  if (!opt->cache || !cache_writable(cache) || url_save == NULL ||
      !strnotempty(url_save) || IS_DELAYED_EXT(url_save))
    return;
  if (cache->kept != NULL) {
    const char *const key =
        concat(OPT_GET_BUFF(opt), OPT_GET_BUFF_SIZE(opt), url_adr, url_fil);

    if (coucal_read(cache->kept, key, NULL) != 0)
      return; /* another attempt at the same link already stored it */
    coucal_add(cache->kept, key, 1);
  }
  /* Headers only: a kept entry carries no body, so nothing is read from the
     previous cache or from disk, whatever the file's size. */
  previous_save[0] = '\0';
  r = cache_readex_(opt, cache, url_adr, url_fil, NULL, NULL, previous_save, 1,
                    HTS_TRUE);
  /* The entry must name this very file: fexist() upstream proves only that
     something occupies the name, which a collision flip fills with another
     URL's file. */
  if (r.statuscode > 0 && strcmp(previous_save, url_save) == 0) {
    hts_log_print(opt, LOG_DEBUG, "keeping the previous cache entry for %s%s",
                  url_adr, url_fil);
    cache_add_ex(opt, cache, &r, url_adr, url_fil, url_save, opt->all_in_cache,
                 StringBuff(opt->path_html_utf8), HTS_TRUE);
  }
}

esp_err_t session_get_history_json(const char *chat_id, char *buf, size_t size, int max_msgs)
{
    char path[64];
    session_path(chat_id, path, sizeof(path));

    FILE *f = fopen(path, "r");
    if (!f) {
        /* No history yet */
        snprintf(buf, size, "[]");
        return ESP_OK;
    }

    /* Read all lines into a ring buffer of cJSON objects */
    cJSON *messages[MIMI_SESSION_MAX_MSGS];
    int count = 0;
    int write_idx = 0;

    char line[2048];
    while (fgets(line, sizeof(line), f)) {
        /* Strip newline */
        size_t len = strlen(line);
        if (len > 0 && line[len - 1] == '\n') line[len - 1] = '\0';
        if (line[0] == '\0') continue;

        cJSON *obj = cJSON_Parse(line);
        if (!obj) continue;

        /* Ring buffer: overwrite oldest if full */
        if (count >= max_msgs) {
            cJSON_Delete(messages[write_idx]);
        }
        messages[write_idx] = obj;
        write_idx = (write_idx + 1) % max_msgs;
        if (count < max_msgs) count++;
    }
    fclose(f);

    /* Build JSON array with only role + content */
    cJSON *arr = cJSON_CreateArray();
    int start = (count < max_msgs) ? 0 : write_idx;
    for (int i = 0; i < count; i++) {
        int idx = (start + i) % max_msgs;
        cJSON *src = messages[idx];

        cJSON *entry = cJSON_CreateObject();
        cJSON *role = cJSON_GetObjectItem(src, "role");
        cJSON *content = cJSON_GetObjectItem(src, "content");
        if (role && content) {
            cJSON_AddStringToObject(entry, "role", role->valuestring);
            cJSON_AddStringToObject(entry, "content", content->valuestring);
        }
        cJSON_AddItemToArray(arr, entry);
    }

    /* Cleanup ring buffer */
    int cleanup_start = (count < max_msgs) ? 0 : write_idx;
    for (int i = 0; i < count; i++) {
        int idx = (cleanup_start + i) % max_msgs;
        cJSON_Delete(messages[idx]);
    }

    char *json_str = cJSON_PrintUnformatted(arr);
    cJSON_Delete(arr);

    if (json_str) {
        strncpy(buf, json_str, size - 1);
        buf[size - 1] = '\0';
        free(json_str);
    } else {
        snprintf(buf, size, "[]");
    }

    return ESP_OK;
}

static void cont_to_f16_sycl(const char * src, sycl::half * dst,
        int64_t ne0, int64_t ne1, int64_t ne2, int64_t ne3,
        size_t nb1, size_t nb2, size_t nb3, dpct::queue_ptr stream) {
    const int64_t n = ne0 * ne1 * ne2 * ne3;
    stream->parallel_for(sycl::range<1>(n), [=](sycl::id<1> ix) {
        const int64_t gid = ix[0];
        int64_t       i   = gid;
        const int64_t i0 = i % ne0; i /= ne0;
        const int64_t i1 = i % ne1; i /= ne1;
        const int64_t i2 = i % ne2; const int64_t i3 = i / ne2;
        const src_t * p = (const src_t *) (src + i1 * nb1 + i2 * nb2 + i3 * nb3) + i0;
        dst[gid] = (sycl::half) (*p);
    });
}

static size_t db_extract_hosts(const char *connstr, char out[][TURN_LONG_STRING_SIZE], size_t max) {
  size_t n = 0;
  if (!connstr || !connstr[0]) {
    return 0;
  }

  if (strstr(connstr, "://")) {
    /* URI form */
    const char *p = strstr(connstr, "://") + 3;
    size_t authlen = strcspn(p, "/?"); /* authority ends at first '/' or '?' */
    char auth[TURN_LONG_STRING_SIZE] = {0};
    if (authlen >= sizeof(auth)) {
      authlen = sizeof(auth) - 1;
    }
    memcpy(auth, p, authlen);
    char *at = strrchr(auth, '@'); /* drop any userinfo */
    char *hostlist = at ? at + 1 : auth;
    char *save = NULL;
    for (char *tok = strtok_r(hostlist, ",", &save); tok && n < max; tok = strtok_r(NULL, ",", &save)) {
      char host[TURN_LONG_STRING_SIZE] = {0};
      if (tok[0] == '[') {
        /* [IPv6]:port */
        char *end = strchr(tok, ']');
        if (end) {
          size_t hl = (size_t)(end - (tok + 1));
          if (hl >= sizeof(host)) {
            hl = sizeof(host) - 1;
          }
          memcpy(host, tok + 1, hl);
        }
      } else {
        size_t hl = strcspn(tok, ":"); /* strip :port */
        if (hl >= sizeof(host)) {
          hl = sizeof(host) - 1;
        }
        memcpy(host, tok, hl);
      }
      if (host[0]) {
        STRCPY(out[n], host);
        ++n;
      }
    }
    return n;
  }

  /* key=value form (space-separated) */
  char buf[TURN_LONG_STRING_SIZE] = {0};
  STRCPY(buf, connstr);
  char *save = NULL;
  for (char *tok = strtok_r(buf, " ", &save); tok && n < max; tok = strtok_r(NULL, " ", &save)) {
    char *eq = strchr(tok, '=');
    if (!eq) {
      continue;
    }
    *eq = 0;
    const char *key = tok;
    const char *val = eq + 1;
    if (!strcmp(key, "host") || !strcmp(key, "ip") || !strcmp(key, "addr") || !strcmp(key, "ipaddr") ||
        !strcmp(key, "hostaddr")) {
      if (val[0]) {
        STRCPY(out[n], val);
        ++n;
      }
    }
  }
  return n;
}

static int test_rapid_drain_refill(void)
{
	struct io_uring ring;
	struct io_uring_buf_ring *br;
	struct io_uring_sqe *sqe;
	struct io_uring_cqe *cqe;
	void *buf_base;
	const char *fname = ".buf-ring-rapid-tmp";
	int fd, ret;
	int total_success = 0;

	ret = io_uring_queue_init(64, &ring, 0);
	if (ret) {
		fprintf(stderr, "ring setup: %d\n", ret);
		return T_EXIT_FAIL;
	}

	br = io_uring_setup_buf_ring(&ring, NR_BUFS, BGID, 0, &ret);
	if (!br) {
		if (ret == -EINVAL || ret == -ENOENT) {
			io_uring_queue_exit(&ring);
			return T_EXIT_SKIP;
		}
		fprintf(stderr, "buf ring setup: %d\n", ret);
		io_uring_queue_exit(&ring);
		return T_EXIT_FAIL;
	}

	buf_base = malloc(NR_BUFS * BUF_SIZE);
	if (!buf_base)
		goto err;

	t_create_file(fname, FILE_SIZE);
	fd = open(fname, O_RDONLY);
	if (fd < 0) {
		perror("open");
		goto err;
	}

	/*
	 * Do many rapid cycles: provide 1 buffer, submit 1 read,
	 * reap, repeat. This tests the fast path of single-buffer
	 * provide/consume cycles.
	 */
	for (int i = 0; i < NR_ROUNDS * NR_BUFS; i++) {
		/* Provide exactly 1 buffer */
		void *addr = buf_base + (i % NR_BUFS) * BUF_SIZE;
		io_uring_buf_ring_add(br, addr, BUF_SIZE, i % NR_BUFS,
				      io_uring_buf_ring_mask(NR_BUFS), 0);
		io_uring_buf_ring_advance(br, 1);

		sqe = io_uring_get_sqe(&ring);
		io_uring_prep_read(sqe, fd, NULL, BUF_SIZE,
				   (i * BUF_SIZE) % FILE_SIZE);
		sqe->flags |= IOSQE_BUFFER_SELECT;
		sqe->buf_group = BGID;
		sqe->user_data = i;

		ret = io_uring_submit(&ring);
		if (ret != 1) {
			fprintf(stderr, "rapid submit %d: %d\n", i, ret);
			goto err_file;
		}

		ret = io_uring_wait_cqe(&ring, &cqe);
		if (ret) {
			fprintf(stderr, "rapid wait %d: %d\n", i, ret);
			goto err_file;
		}

		if (cqe->res <= 0) {
			fprintf(stderr, "rapid read %d res: %d\n", i, cqe->res);
			io_uring_cqe_seen(&ring, cqe);
			goto err_file;
		}

		if (!(cqe->flags & IORING_CQE_F_BUFFER)) {
			fprintf(stderr, "rapid read %d: no buffer flag\n", i);
			io_uring_cqe_seen(&ring, cqe);
			goto err_file;
		}

		total_success++;
		io_uring_cqe_seen(&ring, cqe);
	}

	if (total_success != NR_ROUNDS * NR_BUFS) {
		fprintf(stderr, "rapid: %d success, expected %d\n",
			total_success, NR_ROUNDS * NR_BUFS);
		goto err_file;
	}

	close(fd);
	unlink(fname);
	free(buf_base);
	io_uring_free_buf_ring(&ring, br, NR_BUFS, BGID);
	io_uring_queue_exit(&ring);
	return T_EXIT_PASS;

err_file:
	close(fd);
	unlink(fname);
err:
	free(buf_base);
	io_uring_queue_exit(&ring);
	return T_EXIT_FAIL;
}

void mbedtls_debug_print_psa_ec(const mbedtls_ssl_context *ssl, int level,
                                const char *file, int line,
                                const char *text, const mbedtls_pk_context *pk)
{
    char str[DEBUG_BUF_SIZE];
    const uint8_t *coord_start;
    size_t coord_len;

    if (NULL == ssl              ||
        NULL == ssl->conf        ||
        NULL == ssl->conf->f_dbg ||
        level > debug_threshold) {
        return;
    }

    /* For the description of pk->pk_raw content please refer to the description
     * psa_export_public_key() function. */
    coord_len = (pk->pub_raw_len - 1)/2;

    /* X coordinate */
    coord_start = pk->pub_raw + 1;
    mbedtls_snprintf(str, sizeof(str), "%s(X)", text);
    mbedtls_debug_print_ec_coord(ssl, level, file, line, str, coord_start, coord_len);

    /* Y coordinate */
    coord_start = coord_start + coord_len;
    mbedtls_snprintf(str, sizeof(str), "%s(Y)", text);
    mbedtls_debug_print_ec_coord(ssl, level, file, line, str, coord_start, coord_len);
}

InputSection<E> *find(const Digest &digest) {
    u64 hi;
    u64 lo;
    memcpy(&hi, digest.data(), 8);
    memcpy(&lo, digest.data() + 8, 8);
    u64 done = (round << 49) | (hi >> 16);

    for (i64 i = hi & mask;; i = (i + 1) & mask)
      if (slots[i].hi == done && slots[i].lo == lo)
        return slots[i].leader;
  }

void DataModel::MacroRunner::saveMacro(const QString& source, int language)
{
  const bool lua = (language == SerialStudio::Lua);
  auto* dialog   = new QFileDialog(nullptr,
                                 tr("Save macro"),
                                 macrosDirectory(),
                                 lua ? QStringLiteral("*.lua") : QStringLiteral("*.js"));
  dialog->setAcceptMode(QFileDialog::AcceptSave);
  dialog->setDefaultSuffix(lua ? QStringLiteral("lua") : QStringLiteral("js"));
  dialog->setAttribute(Qt::WA_DeleteOnClose);

  connect(dialog, &QFileDialog::fileSelected, this, [this, source](const QString& path) {
    if (path.isEmpty())
      return;

    QMetaObject::invokeMethod(
      this,
      [this, source, path]() {
        QSaveFile file(path);
        if (!file.open(QFile::WriteOnly | QFile::Truncate)) {
          Q_EMIT scriptError(tr("Cannot write %1").arg(path));
          return;
        }

        const QByteArray payload = source.toUtf8();
        if (file.write(payload) != payload.size() || !file.commit()) {
          Q_EMIT scriptError(tr("Failed to save %1: %2").arg(path, file.errorString()));
          return;
        }

        Q_EMIT macroSaved(QFileInfo(path).fileName());
      },
      Qt::QueuedConnection);
  });

  dialog->open();
}

struct tf_msg * hfscClassAdd(int type, u32 classid, u32 parentid){
    // Kernel Handler: function  hfsc_change_class
    /*
        hfsc_changeclass:
            - If the class exists, the function changes the attributes of the class
            - else, create a new class
    */
    /*
        parentid = 0 means q.root
    */
    FAIL_IF(type!=TCA_HFSC_RSC && type !=TCA_HFSC_FSC);
    struct tf_msg *m = calloc(1,sizeof(struct tf_msg));
    init_tf_msg(m);
    m->nlh.nlmsg_type       = RTM_NEWTCLASS;
    m->tcm.tcm_parent       = parentid;
    m->tcm.tcm_handle       = classid;
    m->nlh.nlmsg_flags      |= NLM_F_CREATE;
    m->nlh.nlmsg_len        += NLMSG_ALIGN(add_rtattr((size_t)m + NLMSG_ALIGN(m->nlh.nlmsg_len), TCA_KIND, strlen("hfsc") + 1, "hfsc"));

    struct rtattr *opts     = (struct rtattr *)((size_t)m + NLMSG_ALIGN(m->nlh.nlmsg_len));
    opts->rta_type          = TCA_OPTIONS;
    opts->rta_len           = RTA_LENGTH(0);
    // Default trafic control policy
    // TODO: Get from parameters
    int dist[3] = {1, 1, 1}; 
    if(type == TCA_HFSC_RSC)
        opts->rta_len += RTA_ALIGN(add_rtattr((size_t)opts + opts->rta_len, TCA_HFSC_RSC, sizeof(dist), (char *)dist));
    else if(type == TCA_HFSC_FSC)
        opts->rta_len += RTA_ALIGN(add_rtattr((size_t)opts + opts->rta_len, TCA_HFSC_FSC, sizeof(dist), (char *)dist));

    m->nlh.nlmsg_len += NLMSG_ALIGN(opts->rta_len);
    return m;
}

NfcCommand mf_plus_listener_auth_continue_handler(MfPlusListener* instance, const BitBuffer* rx) {
    // [AUTH_CONTINUE, E(key, iv=0, rrot(RndA) || rol(RndB)) (32)]
    if(instance->state != MfPlusListenerStateAuthFirstDone) {
        FURI_LOG_D(TAG, "AUTH_CONTINUE without a prior AUTH_FIRST (state=%d)", instance->state);
        mf_plus_listener_send_status(instance, MF_PLUS_STATUS_AUTH_ERROR);
        return NfcCommandContinue;
    }
    if(bit_buffer_get_size_bytes(rx) < 1 + 2 * MF_PLUS_AES_BLOCK_SIZE) {
        FURI_LOG_D(TAG, "AUTH_CONTINUE frame too short");
        mf_plus_listener_send_status(instance, MF_PLUS_STATUS_AUTH_ERROR);
        return NfcCommandContinue;
    }

    const uint8_t zero_iv[MF_PLUS_AES_BLOCK_SIZE] = {0};
    uint8_t dec[2 * MF_PLUS_AES_BLOCK_SIZE];
    mf_plus_crypto_cbc_decrypt(
        instance->auth_key.data, zero_iv, bit_buffer_get_data(rx) + 1, dec, sizeof(dec));

    // dec = rrot(RndA) || rol(RndB). The RndB echo proves the reader holds our key.
    uint8_t rnd_b_rot[MF_PLUS_AES_BLOCK_SIZE];
    mf_plus_crypto_rotate_left(instance->rnd_b, rnd_b_rot);
    if(memcmp(&dec[MF_PLUS_AES_BLOCK_SIZE], rnd_b_rot, MF_PLUS_AES_BLOCK_SIZE) != 0) {
        // Wrong key: the reader's token doesn't echo our RndB. NAK so a key check (PM3 `hf mfp chk`)
        // records a miss and advances instead of hanging on a timeout, which would desync its scan.
        FURI_LOG_D(TAG, "AUTH_CONTINUE RndB echo mismatch");
        mf_plus_listener_reset_session(instance);
        mf_plus_listener_send_status(instance, MF_PLUS_STATUS_AUTH_ERROR);
        return NfcCommandContinue;
    }

    const uint8_t* rnd_a_rrot = &dec[0]; // the value the card treats as RndA (rrot(RndA))

    // Establish the session: fresh TI, counters reset, session keys from rrot(RndA) + RndB (the
    // same inputs the poller derives from).
    MfPlusListenerSession* s = &instance->session;
    furi_hal_random_fill_buf(s->ti, sizeof(s->ti));
    s->r_ctr = 0;
    s->w_ctr = 0;
    mf_plus_crypto_derive_session_keys(
        instance->auth_key.data, rnd_a_rrot, instance->rnd_b, s->k_enc, s->k_mac);

    // Response = E(key, iv=0, TI(4) || RndA'(16) || caps). The reader expects rol(RndA). One
    // rotate-left of the extracted value satisfies both readers: for this port's poller (which put
    // rrot(RndA) here) it yields RndA (its 3rd accepted variant), and for a PM3-style reader (which
    // put RndA here) it yields rol(RndA). The cap bytes after are unused by the poller.
    uint8_t rnd_a_echo[MF_PLUS_AES_BLOCK_SIZE];
    mf_plus_crypto_rotate_left(rnd_a_rrot, rnd_a_echo);

    uint8_t plain[2 * MF_PLUS_AES_BLOCK_SIZE] = {0};
    memcpy(&plain[0], s->ti, 4);
    memcpy(&plain[4], rnd_a_echo, MF_PLUS_AES_BLOCK_SIZE);

    uint8_t resp[1 + 2 * MF_PLUS_AES_BLOCK_SIZE];
    resp[0] = MF_PLUS_STATUS_OK;
    mf_plus_crypto_cbc_encrypt(instance->auth_key.data, zero_iv, plain, &resp[1], sizeof(plain));

    mf_plus_listener_send(instance, resp, sizeof(resp));
    instance->state = MfPlusListenerStateAuthenticated;
    return NfcCommandContinue;
}

static void endpt_respond_msg_too_large( pjsip_endpoint *endpt,
                                         pjsip_rx_data *rdata )
{
    const pj_str_t end_hdr = { "\n\r\n", 3 };
    pj_str_t received;
    pj_size_t hdr_len;
    char *pos;
    char *hdr_buf;
    pjsip_msg *msg;
    pjsip_warning_hdr *warn;
    pjsip_hdr hdr_list;
    char warn_text[80];
    pj_str_t warn_str;
    pj_status_t status;

    received.ptr = rdata->msg_info.msg_buf;
    received.slen = rdata->msg_info.len;
    if (received.ptr == NULL || received.slen <= 0)
        return;

    /* Locate the empty line that ends the header block, with the sentinel
     * pjsip_find_msg() uses, so the two cannot disagree on where the headers
     * end. Keep the line: the parser needs it to see that they are complete.
     */
    pos = pj_strstr(&received, &end_hdr);
    if (pos == NULL)
        return;
    hdr_len = (pj_size_t)(pos + 3 - received.ptr);

    /* Parse from a copy: the scanner writes into the buffer it is given, and
     * the transport still hands the original on to its dropped-data callback.
     */
    hdr_buf = (char*) pj_pool_alloc(rdata->tp_info.pool, hdr_len + 1);
    pj_memcpy(hdr_buf, received.ptr, hdr_len);
    hdr_buf[hdr_len] = '\0';

    pj_bzero(&rdata->msg_info, sizeof(rdata->msg_info));
    pj_list_init(&rdata->msg_info.parse_err);
    rdata->msg_info.msg_buf = hdr_buf;
    rdata->msg_info.len = (int)hdr_len;
    pj_bzero(&rdata->endpt_info, sizeof(rdata->endpt_info));

    msg = pjsip_parse_rdata(hdr_buf, hdr_len, rdata);
    if (msg == NULL || !pj_list_empty(&rdata->msg_info.parse_err) ||
        msg->type != PJSIP_REQUEST_MSG ||
        msg->line.req.method.id == PJSIP_ACK_METHOD ||
        rdata->msg_info.via == NULL || rdata->msg_info.from == NULL ||
        rdata->msg_info.to == NULL || rdata->msg_info.cseq == NULL ||
        rdata->msg_info.cid == NULL || rdata->msg_info.cid->id.slen == 0)
    {
        return;
    }

    /* The transport layer adds these for every request it accepts, and
     * pjsip_get_response_addr() relies on them. We bypassed it, so do it here.
     */
    pj_strdup2(rdata->tp_info.pool, &rdata->msg_info.via->recvd_param,
               rdata->pkt_info.src_name);
    if (rdata->msg_info.via->rport_param == 0)
        rdata->msg_info.via->rport_param = rdata->pkt_info.src_port;

    /* Name the actual limit, so the peer learns what to stay under. */
    pj_ansi_snprintf(warn_text, sizeof(warn_text),
                     "Message exceeds the %d byte receive buffer",
                     PJSIP_MAX_PKT_LEN);
    warn_str = pj_str(warn_text);

    pj_list_init(&hdr_list);
    warn = pjsip_warning_hdr_create(rdata->tp_info.pool, 399,
                                    pjsip_endpt_name(endpt), &warn_str);
    if (warn)
        pj_list_push_back(&hdr_list, (pjsip_hdr*)warn);

    status = pjsip_endpt_respond_stateless(endpt, rdata,
                                           PJSIP_SC_MESSAGE_TOO_LARGE, NULL,
                                           &hdr_list, NULL);
    if (status != PJ_SUCCESS) {
        char errmsg[PJ_ERR_MSG_SIZE];

        pj_strerror(status, errmsg, sizeof(errmsg));
        PJ_LOG(3, (THIS_FILE, "Unable to respond %d to the oversized request "
                              "from %s:%d: %s",
                   PJSIP_SC_MESSAGE_TOO_LARGE, rdata->pkt_info.src_name,
                   rdata->pkt_info.src_port, errmsg));
    }
}

ld_elf_eh_frame_hdr_result_t ld_elf_eh_frame_hdr_encode(
        uint8_t *output, size_t output_size, uint64_t header_address,
        uint64_t eh_frame_address,
        const ld_elf_eh_frame_hdr_entry_t *entries, size_t entry_count,
        size_t *error_entry_index) {
    if (error_entry_index) *error_entry_index = SIZE_MAX;

    size_t encoded_size;
    ld_elf_eh_frame_hdr_result_t size_result =
            ld_elf_eh_frame_hdr_size(entry_count, &encoded_size);
    if (size_result != LD_ELF_EH_FRAME_HDR_OK) return size_result;
    if (!output || (entry_count != 0U && !entries))
        return LD_ELF_EH_FRAME_HDR_INVALID_ARGUMENT;
    if (output_size < encoded_size)
        return LD_ELF_EH_FRAME_HDR_OUTPUT_TOO_SMALL;
    if (entry_count > SIZE_MAX / sizeof(ld_elf_eh_frame_hdr_work_entry_t))
        return LD_ELF_EH_FRAME_HDR_WORK_SIZE_OVERFLOW;
    if (header_address > UINT64_MAX - 4U)
        return LD_ELF_EH_FRAME_HDR_EH_FRAME_POINTER_RANGE;

    int32_t eh_frame_pointer_relative;
    if (!ld_elf_eh_frame_hdr_relative_i32(
                eh_frame_address, header_address + 4U,
                &eh_frame_pointer_relative))
        return LD_ELF_EH_FRAME_HDR_EH_FRAME_POINTER_RANGE;

    ld_elf_eh_frame_hdr_work_entry_t *work = NULL;
    if (entry_count != 0U) {
        work = malloc(entry_count * sizeof(*work));
        if (!work) return LD_ELF_EH_FRAME_HDR_OUT_OF_MEMORY;
        for (size_t i = 0; i < entry_count; i++) {
            work[i].first_pc = entries[i].first_pc;
            work[i].fde_address = entries[i].fde_address;
            work[i].original_index = i;
        }
        qsort(work, entry_count, sizeof(*work),
              ld_elf_eh_frame_hdr_compare_entries);
    }

    for (size_t i = 0; i < entry_count; i++) {
        if (!ld_elf_eh_frame_hdr_relative_i32(
                    work[i].first_pc, header_address,
                    &work[i].first_pc_relative)) {
            if (error_entry_index)
                *error_entry_index = work[i].original_index;
            free(work);
            return LD_ELF_EH_FRAME_HDR_FIRST_PC_RANGE;
        }
        if (!ld_elf_eh_frame_hdr_relative_i32(
                    work[i].fde_address, header_address,
                    &work[i].fde_address_relative)) {
            if (error_entry_index)
                *error_entry_index = work[i].original_index;
            free(work);
            return LD_ELF_EH_FRAME_HDR_FDE_ADDRESS_RANGE;
        }
    }

    output[0] = 1U;
    output[1] = 0x1bU; /* DW_EH_PE_pcrel | DW_EH_PE_sdata4 */
    output[2] = 0x03U; /* DW_EH_PE_udata4 */
    output[3] = 0x3bU; /* DW_EH_PE_datarel | DW_EH_PE_sdata4 */
    ld_elf_eh_frame_hdr_write_u32(output + 4U,
                                  (uint32_t) eh_frame_pointer_relative);
    ld_elf_eh_frame_hdr_write_u32(output + 8U, (uint32_t) entry_count);
    for (size_t i = 0; i < entry_count; i++) {
        uint8_t *encoded_entry =
                output + LD_ELF_EH_FRAME_HDR_FIXED_SIZE +
                i * LD_ELF_EH_FRAME_HDR_ENTRY_SIZE;
        ld_elf_eh_frame_hdr_write_u32(
                encoded_entry, (uint32_t) work[i].first_pc_relative);
        ld_elf_eh_frame_hdr_write_u32(
                encoded_entry + 4U,
                (uint32_t) work[i].fde_address_relative);
    }

    free(work);
    return LD_ELF_EH_FRAME_HDR_OK;
}

LOCAL int ftp_process_client_line(ArkimeSession_t *session, const char *line, int len)
{
    while (len > 0 && (*line == ' ' || *line == '\t')) {
        line++;
        len--;
    }
    if (len < 3)
        return 0;

    const char *space = memchr(line, ' ', len);
    int cmdLen = space ? (int)(space - line) : len;
    if (cmdLen < 3 || cmdLen > 8)
        return 0;

    char cmd[16];
    int i;
    for (i = 0; i < cmdLen; i++) {
        if (!isalpha((uint8_t)line[i]))
            return 0;
        cmd[i] = toupper((uint8_t)line[i]);
    }
    cmd[cmdLen] = 0;

    if (strcmp(cmd, "HELO") == 0 || strcmp(cmd, "EHLO") == 0 || strcmp(cmd, "LHLO") == 0)
        return 1;

    const char *arg = space ? space + 1 : NULL;
    int argLen = space ? (len - cmdLen - 1) : 0;
    while (argLen > 0 && (*arg == ' ' || *arg == '\t')) {
        arg++;
        argLen--;
    }
    while (argLen > 0 && (arg[argLen - 1] == '\r' || arg[argLen - 1] == ' ' || arg[argLen - 1] == '\t')) {
        argLen--;
    }

    arkime_field_string_add(commandField, session, cmd, cmdLen, TRUE);

    if (argLen <= 0)
        return 0;

    if (strcmp(cmd, "USER") == 0) {
        arkime_field_string_add_lower(userField, session, arg, argLen);
    } else if (strcmp(cmd, "PASS") == 0) {
        arkime_session_add_tag(session, "ftp:password");
    } else if (strcmp(cmd, "RETR") == 0 || strcmp(cmd, "STOR") == 0 ||
               strcmp(cmd, "STOU") == 0 || strcmp(cmd, "APPE") == 0 ||
               strcmp(cmd, "DELE") == 0 || strcmp(cmd, "RNFR") == 0 ||
               strcmp(cmd, "RNTO") == 0 || strcmp(cmd, "MKD")  == 0 ||
               strcmp(cmd, "RMD")  == 0 || strcmp(cmd, "SIZE") == 0 ||
               strcmp(cmd, "MDTM") == 0) {
        arkime_field_string_add(filenameField, session, arg, argLen, TRUE);
    }
    return 0;
}

ssize_t slurp(std::string *r, const char *path) {
    int fd;
    if ((fd = open(path, O_RDONLY)) == -1)
        return -1;
    size_t toto = 0;
    size_t orig = r->size();
    for (;;) {
        size_t want = 16384;
        size_t size = r->size();
        r->resize(size + want);
        ssize_t rc;
        if ((rc = read(fd, r->data() + size, want)) == -1) {
            r->resize(orig);
            close(fd);
            return -1;
        }
        size_t got = rc;
        r->resize(size + got);
        toto += got;
        if (!got)
            break;
    }
    if (close(fd)) {
        r->resize(orig);
        return -1;
    }
    return toto;
}

